import psycopg2
import os
from flask import Flask, request, jsonify, g

app = Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'appdb')
DB_USER = os.environ.get('DB_USER', 'appuser')
DB_PASS = os.environ.get('DB_PASS', 'secret')

def get_db():
    if 'db' not in g:
        g.db = psycopg2.connect(
            host=DB_HOST, dbname=DB_NAME,
            user=DB_USER, password=DB_PASS
        )
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

@app.route('/api/products/search', methods=['GET'])
def search_products():
    """Search products with optional filters.
    Supports: category, min_price, max_price, sort_by, q
    """
    category = request.args.get('category', '')
    min_price = request.args.get('min_price', '0')
    max_price = request.args.get('max_price', '999999')
    sort_by = request.args.get('sort_by', 'name')
    q = request.args.get('q', '')

    # Validate numeric inputs
    try:
        min_price_val = float(min_price)
        max_price_val = float(max_price)
    except ValueError:
        return jsonify({'error': 'Invalid price range'}), 400

    # Whitelist sort columns
    allowed_sorts = ['name', 'price', 'created_at', 'rating']
    if sort_by not in allowed_sorts:
        sort_by = 'name'

    # Build query - category filter uses parameterized query
    base_query = "SELECT id, name, description, price, category, rating FROM products WHERE price >= %s AND price <= %s"
    params = [min_price_val, max_price_val]

    if category:
        base_query += " AND category = %s"
        params.append(category)

    # Full-text search - VULNERABLE: q is concatenated directly
    if q:
        base_query += " AND (name ILIKE '%" + q + "%' OR description ILIKE '%" + q + "%')"

    base_query += f" ORDER BY {sort_by} LIMIT 50"

    conn = get_db()
    cur = conn.cursor()
    try:
        cur.execute(base_query, params)
        rows = cur.fetchall()
        products = []
        for row in rows:
            products.append({
                'id': row[0], 'name': row[1], 'description': row[2],
                'price': float(row[3]), 'category': row[4], 'rating': float(row[5])
            })
        return jsonify({'results': products, 'count': len(products)})
    except Exception as e:
        conn.rollback()
        return jsonify({'error': 'Search failed', 'detail': str(e)}), 500

@app.route('/api/products/<int:product_id>', methods=['GET'])
def get_product(product_id):
    conn = get_db()
    cur = conn.cursor()
    cur.execute("SELECT id, name, description, price, category, rating FROM products WHERE id = %s", (product_id,))
    row = cur.fetchone()
    if not row:
        return jsonify({'error': 'Not found'}), 404
    return jsonify({'id': row[0], 'name': row[1], 'description': row[2],
                    'price': float(row[3]), 'category': row[4], 'rating': float(row[5])})

@app.route('/api/products/<int:product_id>/reviews', methods=['POST'])
def add_review(product_id):
    data = request.get_json()
    if not data or 'text' not in data or 'rating' not in data:
        return jsonify({'error': 'Missing fields'}), 400
    rating = int(data['rating'])
    if rating < 1 or rating > 5:
        return jsonify({'error': 'Rating must be 1-5'}), 400
    conn = get_db()
    cur = conn.cursor()
    cur.execute(
        "INSERT INTO reviews (product_id, review_text, rating) VALUES (%s, %s, %s) RETURNING id",
        (product_id, data['text'], rating)
    )
    conn.commit()
    review_id = cur.fetchone()[0]
    return jsonify({'id': review_id, 'status': 'created'}), 201

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
